# -*- coding: utf-8 -*-
"""B14 收口门面（`content/catalog_rules.py`）—— 宿主尾部长尾名的**包内读口**。

为什么单开一个文件
------------------
B14 收口要把宿主 `game/**` 里的 55 条 `from ..data… import …` 全改读包内源（判据：
**删掉 `game/data` 后宿主仍能 import**）。其中 36 个名字里，有 22 个**不在**
`catalog_{core,items,life,quests,space,b143}.py` 任何既有门面里、也不属
`content/mech/*` · `content/tables.py` · `content/skills.py` 这些既有模块 ——
它们是 rule/常量/文案池一类的「尾部长尾名」。本文件就是它们的家。

与 `catalog_b143.py` 同款纪律
-----------------------------
* **只读包内数据**（`content/rules/*.json` · `content/data/*.json`）；**零宿主 import**、
  不用 `_host_attr`/`_HostMod`（宿主 `game/data` 删掉后本模块照样活）。
* 域读不到（缺文件/坏 JSON）→ 返回 `{}` / `[]` **不抛**（空表会在门禁上以「不等」现形）。
* **不改形状**：不设默认值、不改数值、不重排键（`cmp_val` 连键序一起比，见
  `overnight/b14_catalog_gate.py`）。

三个来源（逐名台账见下）
------------------------
① **包内域 JSON**（这是真域，编辑器可改）——
   `EFFECT_RULES`(`rules/effect_rules.json`) · `BAR_STATE_PREFIX`(`rules/game_config.json`
   `battle_rules` 组) · `FORMULA_SKELETON`(同文件 `formula_skeleton` 组) ·
   `FIELD_TIER_MULT`(同文件 `stat_templates` 组) · `DROP_POOLS`(`data/drop_pools.json`) ·
   `PLAYER_BASE_GROWTH`(`rules/panel_rules.json` 的 `base_growth` 组，**tuple 还原**)。

② **派生**——`EVENT_WEIGHT_SUM` / `EXPLORE_EGG_SUM`：宿主真源就是
   `sum(e["weight"] for e in EXPLORE_EVENTS / EXPLORE_EGG_EVENTS)`，此处按
   `events` 域的 `source` 字段现算（`explore`=100 · `egg`=46，与真源池同源）。

③ **逐字字面量（包内无域）**——14 个名字的域**从未被导出器建过**（见
   `overnight/W2_host_data_imports.md` §遗留）：
   `EXPLORE_EGG_CHANCE` · `WEAPON_TYPES` · `WEAPON_NAME_SUFFIX` · `EQUIP_NAME_PREFIX` ·
   `EQUIP_PREFIX_FLAVOR` · `EQUIP_NAME_SUFFIX` · `SET_THEMES` · `SET_CHANCE` · `SERIES_SETS` ·
   `NOTE_POOL` · `RUNE_POOL` · `SIGHT_POOL` · `DAILY_MAP_EVENTS` · `SUPPLY_BOX`。
   值由 `overnight/w2_gen_catalog_rules.py` 从宿主真源 **import 后 pprint dump**
   （非手抄，键序/嵌套/类型原样），与 `content/mech/params.py` 的 `FORMULA_SKELETON`
   「切片期随代码走」同一路数；**待建域**后即可改为 ①（本文件是它们唯一读口，
   改一处即可切）。

⚠️ 两处类型还原（不做 = 静默错值/门禁报红）
-------------------------------------------
* `PLAYER_BASE_GROWTH["linear_stats"]`：域 JSON 只有 array，真源是 **tuple**
  （`game/data/base_growth.py`）→ 不还原 = `cmp_val` 报「类型不同 list vs tuple」。
* `EXPLORE_EGG_CHANCE` 是 float：字面量按 repr dump，往返精确（0.005）。
"""
from __future__ import annotations

import json
import os

_HERE = os.path.dirname(os.path.abspath(__file__))
_DATA_DIR = os.path.join(_HERE, "data")
_RULES_DIR = os.path.join(_HERE, "rules")


def _read_json(path: str, default):
    """读包内 JSON（缺文件 / 坏 JSON / 权限 → default，不抛；与 `content/tables.py` 同款）。"""
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return default


def _read_domain(domain: str, sub: str, default):
    """读包内 `content/<sub>/<domain>.json`（`sub` = data|rules）。"""
    return _read_json(os.path.join(_HERE, sub, f"{domain}.json"), default)


def _read_group(domain: str, sub: str, group: str, key: str, default=None):
    """取某域里一个 **常量组** 里的某个键（域/组/键缺 → default）。"""
    dom = _read_domain(domain, sub, None)
    if not isinstance(dom, dict):
        return default
    grp = dom.get(group)
    return grp.get(key, default) if isinstance(grp, dict) else default


# ============================================================
# 类型/序还原（不做 = 静默错值 or 门禁报红；与 `catalog_b143.py` 同款）
# ============================================================

def _tupled_rows(rows):
    """`list[list]` → **`tuple[tuple]`**：真源侧是 **tuple 行表**（如 `BOSS_ATK_LEGACY["seg"]` 的
    `((上限, 每级增量), …)`、`FIELD_TIER_MULT['elite']` 的 `((等级上限, 倍率), …)`），
    JSON 只有 array ⇒ 不还原 = 与真源 `type` 不等（`b14_catalog_gate.cmp_val` 报「类型不同
    list vs tuple」）。

    消费端 `for _lv, _v in seg` 对两种都成立，但**判等/入集合/切片语义**要求 tuple。
    """
    if not isinstance(rows, (list, tuple)):
        return rows
    return tuple(tuple(x) if isinstance(x, list) else x for x in rows)


def _ordered(tbl, order, where: str):
    """按**声明序**排外层键（域 JSON 是字典序，真源是插入序）。

    ⚠️ 序 = 行为：`content/effects/potion_effects` 那类 `for k, v in EFFECT_RULES.items(): … break`
    的「首个命中者」语义直接吃插入序。域读不到 → `{}` 不抛；域在但键集与声明不符 → `raise`
    （防「源改了、门面静默改序」）。
    """
    if not isinstance(tbl, dict) or not tbl:
        return {}
    keys = list(order)
    if len(set(keys)) != len(keys):
        raise ValueError(f"catalog_rules：{where} 的序声明有重复键 —— 拒绝静默取首个")
    have = set(tbl)
    miss = [k for k in keys if k not in have]
    extra = [k for k in have if k not in set(keys)]
    if miss or extra:
        raise ValueError(
            "catalog_rules：%s 域与序声明不一致（域缺 %d / 声明缺 %d）—— 请重跑 "
            "overnight/w2_gen_catalog_rules.py 同步序声明。域缺 %s … 未声明 %s …"
            % (where, len(miss), len(extra), miss[:5], sorted(extra)[:5]))
    return {k: tbl[k] for k in keys}



